// Simple algorithms for arrays. Sorting routines operate on numeric values.
fn linear_search(values, target) { "Return the first matching index, or -1 when not found."; let i = 0; while (i < len(values)) { if (values[i] == target) { return i; } i++; } return -1; }
fn binary_search(sorted_values, target) { "Search an ascending sorted array; return matching index or -1."; let low = 0; let high = len(sorted_values) - 1; while (low <= high) { let middle = floor((low + high) / 2); if (sorted_values[middle] == target) { return middle; } if (sorted_values[middle] < target) { low = middle + 1; } else { high = middle - 1; } } return -1; }
fn sorted(values) { "Return a new ascending-sorted copy of a numeric array using insertion sort."; let result = []; let i = 0; while (i < len(values)) { push(result, values[i]); i++; } i = 1; while (i < len(result)) { let current = result[i]; let j = i - 1; while (j >= 0 && result[j] > current) { result[j + 1] = result[j]; j--; } result[j + 1] = current; i++; } return result; }
fn reversed(values) { "Return a reversed shallow copy of an array."; let result = []; let i = len(values) - 1; while (i >= 0) { push(result, values[i]); i--; } return result; }
